using System;
using System.Collections.Generic;

namespace BonBon.Entities.Models;

/// <summary>
/// Single platform login and shared identity/contact data.
/// </summary>
public partial class account
{
    public Guid account_id { get; set; }

    public string email { get; set; }

    /// <summary>
    /// Encoded hash generated by the authentication library; never plaintext.
    /// </summary>
    public string password_hash { get; set; }

    public string full_name { get; set; }

    public string display_name { get; set; }

    public string phone { get; set; }

    public string status { get; set; }

    public DateTime created_at { get; set; }

    public virtual ICollection<account_role> account_roles { get; set; } = new List<account_role>();
}
